INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Muss ich bei der Subnetzplanung die IP-Bereiche festlegen?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert Netzwerke"}, {"text": "Nein", "correct": false, "because": "Kern der Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schrittweite nutze ich bei 192.168.1.0/24 für /27?', 3, '[{"text": "32", "correct": true, "because": "2^(32-27) = 32"}, {"text": "64", "correct": false, "because": "Für /26"}, {"text": "16", "correct": false, "because": "Für /28"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Subnetzplanung teilt IP-Bereiche. b) Zuweisung ignoriert Hostanzahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuweisung berücksichtigt Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Subnetzplanung?', 4, '[{"text": "IP-Bereiche", "correct": false, "because": "Kern der Planung"}, {"text": "Hostanzahl", "correct": false, "because": "Bestimmt Maske"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.0/26 den Bereich bis 192.168.1.63 hat?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 64, 0-63"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich folgt auf 10.0.0.0/24 mit /25?', 3, '[{"text": "10.0.0.128-10.0.0.255", "correct": true, "because": "Inkrement 128"}, {"text": "10.0.0.64-10.0.0.127", "correct": false, "because": "Für /26"}, {"text": "10.0.1.0-10.0.1.255", "correct": false, "because": "Falsches Inkrement"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Subnetzplanung?', 5, '[{"text": "Bereichsaufteilung", "correct": true, "because": "Definiert Subnetze"}, {"text": "Hostzuweisung", "correct": true, "because": "Bestimmt Nutzung"}, {"text": "Protokollwahl", "correct": false, "because": "Irrelevant"}, {"text": "Bandbreitenmessung", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /28 teilt 192.168.1.0 in 16 Bereiche. b) Zuweisung ist zufällig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(28-24) = 16, b) ist geplant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Subnetzplanung?', 4, '[{"text": "Netzwerkmaske", "correct": false, "because": "Definiert Bereiche"}, {"text": "Hostbedarf", "correct": false, "because": "Bestimmt Größe"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat 172.16.0.0/22 den Bereich bis 172.16.3.255?', 2, '[{"text": "Ja", "correct": true, "because": "Inkrement 1.024, 0.0-3.255"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist der vierte bei 192.168.1.0/24 mit /26?', 4, '[{"text": "192.168.1.192-192.168.1.255", "correct": true, "because": "Inkrement 64, 4. Bereich"}, {"text": "192.168.1.128-192.168.1.191", "correct": false, "because": "3. Bereich"}, {"text": "192.168.2.0-192.168.2.63", "correct": false, "because": "Falsches Netz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Subnetzplanung ohne Bereiche möglich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bereiche sind essenziell"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Subnetzplanung?', 3, '[{"text": "Hostbedarf", "correct": true, "because": "Bestimmt Maske und Bereiche"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /30 hat 4 Adressen pro Bereich. b) Zuweisung ignoriert Subnetze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(32-30) = 4, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche ergeben sich bei 10.0.0.0/24 mit /26?', 5, '[{"text": "10.0.0.0-10.0.0.63", "correct": true, "because": "Inkrement 64"}, {"text": "10.0.0.64-10.0.0.127", "correct": true, "because": "2. Bereich"}, {"text": "10.0.0.128-10.0.0.191", "correct": true, "because": "3. Bereich"}, {"text": "10.0.0.192-10.0.0.255", "correct": true, "because": "4. Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Subnetzplanung unwichtig?', 3, '[{"text": "IP-Bereiche", "correct": false, "because": "Definiert Subnetze"}, {"text": "Hostzuweisung", "correct": false, "because": "Bestimmt Nutzung"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beginnt der 2. Bereich bei 192.168.1.0/25 mit 192.168.1.128?', 3, '[{"text": "Ja", "correct": true, "because": "Inkrement 128"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /29 bei 172.16.0.0/24 32 Bereiche ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "2^(29-24) = 32"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist der dritte bei 10.0.0.0/23 mit /25?', 4, '[{"text": "10.0.0.256-10.0.0.383", "correct": true, "because": "Inkrement 128, 3. Bereich"}, {"text": "10.0.0.128-10.0.0.255", "correct": false, "because": "2. Bereich"}, {"text": "10.0.0.384-10.0.0.511", "correct": false, "because": "4. Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske wähle ich für 6 Hosts pro Subnetz?', 3, '[{"text": "/29", "correct": true, "because": "2^(32-29) - 2 = 6"}, {"text": "/30", "correct": false, "because": "Nur 2 Hosts"}, {"text": "28", "correct": false, "because": "14 Hosts"}]');
